public sealed class Order
{
    public void Ship(DateOnly shipDate)
    {
        if (Lines.Count == 0) throw new InvalidOperationException("Empty order");
        ShippedAt = shipDate;
    }
    public IReadOnlyList<OrderLine> Lines { get; } = [];
    public DateOnly? ShippedAt { get; private set; }
}

public record OrderDto(int Id, DateOnly? ShippedAt);

public readonly record struct CsvRow(int UserId, int Score);

public static IEnumerable<CsvRow> ParseRows(StreamReader reader)
{
    string? line;
    while ((line = reader.ReadLine()) is not null)
    {
        if (TryParseRow(line.AsSpan(), out var uid, out var score))
            yield return new CsvRow(uid, score);
    }
}

public async Task<Result<OrderDto>> GetAsync(int id, CancellationToken ct)
{
    var order = await _repo.FindAsync(id, ct);
    return order is null
        ? Result<OrderDto>.NotFound()
        : Result<OrderDto>.Ok(new OrderDto(order.Id, order.ShippedAt));
}

